import { Component, input, signal } from '@angular/core';

@Component({
  selector: 'app-counter',
  template: `
    <p>{{ label() }}: {{ count() }}</p>
    <button (click)="count.update((n) => n + 1)">Add</button>
  `,
})
export class Counter {
  readonly label = input('Count');
  readonly count = signal(0);
}

import { TestBed } from '@angular/core/testing';
import { Counter } from './counter';

describe('Counter', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({ imports: [Counter] }).compileComponents();
  });

  it('shows the label and the initial count', async () => {
    const fixture = TestBed.createComponent(Counter);
    fixture.componentRef.setInput('label', 'Clicks');
    await fixture.whenStable();

    const element = fixture.nativeElement as HTMLElement;
    expect(element.querySelector('p')?.textContent).toBe('Clicks: 0');
  });

  it('increments when the button is clicked', async () => {
    const fixture = TestBed.createComponent(Counter);
    await fixture.whenStable();

    const element = fixture.nativeElement as HTMLElement;
    element.querySelector('button')?.click();
    await fixture.whenStable();

    expect(element.querySelector('p')?.textContent).toBe('Count: 1');
  });
});

import { TestBed } from '@angular/core/testing';
import { CartService } from './cart-service';

describe('CartService', () => {
  it('adds items and computes the total', () => {
    const cart = TestBed.inject(CartService);

    cart.add({ id: 1, name: 'Keyboard', price: 49 });
    cart.add({ id: 2, name: 'Mouse', price: 19 });

    expect(cart.count()).toBe(2);
    expect(cart.total()).toBe(68);
  });

  it('removes an item by id', () => {
    const cart = TestBed.inject(CartService);
    cart.add({ id: 1, name: 'Keyboard', price: 49 });

    cart.remove(1);

    expect(cart.list()).toEqual([]);
  });
});

