import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { Product, ProductsApi } from './products-api';

describe('ProductsApi', () => {
  beforeEach(() => {
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting()],
    });
  });

  it('loads products from /api/products', () => {
    const api = TestBed.inject(ProductsApi);
    const http = TestBed.inject(HttpTestingController);
    let received: Product[] = [];

    api.list().subscribe((products) => (received = products));

    const request = http.expectOne('/api/products');
    expect(request.request.method).toBe('GET');
    request.flush([{ id: 1, name: 'Keyboard', price: 49 }]);

    expect(received).toEqual([{ id: 1, name: 'Keyboard', price: 49 }]);
    http.verify();
  });
});
